function splitAddress(addr, bits) {
  var out = [];
  for (var i = bits.length - 1; i >= 0; i--) {
    var m = Math.pow(2, bits[i]);
    out.unshift(addr % m);
    addr = Math.floor(addr / m);
  }
  return out;
}
function tlbHits(entries, pages) {
  var tlb = [], hits = 0;
  for (var i = 0; i < pages.length; i++) {
    var at = tlb.indexOf(pages[i]);
    if (at >= 0) { hits++; tlb.splice(at, 1); }
    else if (tlb.length === entries) tlb.shift();
    tlb.push(pages[i]);
  }
  return hits;
}
